import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class HighscoreSpeicher {

    public static void main(String[] args) {
        Path datei = Path.of("highscore.txt");
        try {
            Files.writeString(datei, "Alice 100\nBob 80\nCem 60");
            System.out.println(Files.readString(datei));
        } catch (IOException e) {
            System.out.println("Datei-Problem: " + e.getMessage());
        }
    }
}
